//! Python module `neuron_py`: the compiler API of `neuron-wasm` for Python services.
//!
//! Every function takes strings and returns one JSON string; the shapes are documented
//! in `neuron_wasm::api`. The module has no state, so it is safe to call from any thread
//! (the GIL is released while the compiler runs).
//!
//! ```python
//! import json, neuron_py
//! files = json.dumps({"blink.neuron": open("blink.neuron").read()})
//! report = json.loads(neuron_py.check(files))
//! ```
#![allow(unsafe_code)] // generated by the PyO3 macros; this file has no `unsafe` of its own

use neuron_wasm::api;
use pyo3::prelude::*;

/// `check(files_json) -> str`: diagnostics of a package.
#[pyfunction]
fn check(py: Python<'_>, files_json: &str) -> String {
    py.allow_threads(|| api::check(files_json))
}

/// `format(text) -> str`: the canonical formatting of one source text.
#[pyfunction]
fn format(py: Python<'_>, text: &str) -> String {
    py.allow_threads(|| api::format(text))
}

/// `hover(files_json, file, offset) -> str`: declaration and type under the cursor.
#[pyfunction]
fn hover(py: Python<'_>, files_json: &str, file: &str, offset: usize) -> String {
    py.allow_threads(|| api::hover(files_json, file, offset))
}

/// `definition(files_json, file, offset) -> str`: where the name under the cursor is declared.
#[pyfunction]
fn definition(py: Python<'_>, files_json: &str, file: &str, offset: usize) -> String {
    py.allow_threads(|| api::definition(files_json, file, offset))
}

/// `run(files_json, end_ns, scenario=None) -> str`: runs the program in the interpreter.
#[pyfunction]
#[pyo3(signature = (files_json, end_ns, scenario=None))]
fn run(py: Python<'_>, files_json: &str, end_ns: i64, scenario: Option<&str>) -> String {
    py.allow_threads(|| api::run(files_json, end_ns, scenario))
}

/// `test(files_json) -> str`: runs every `test` block.
#[pyfunction]
fn test(py: Python<'_>, files_json: &str) -> String {
    py.allow_threads(|| api::test(files_json))
}

/// `emit(lang, files_json, profile=None) -> str`: translates the program to another language.
#[pyfunction]
#[pyo3(signature = (lang, files_json, profile=None))]
fn emit(py: Python<'_>, lang: &str, files_json: &str, profile: Option<&str>) -> String {
    py.allow_threads(|| api::emit(lang, files_json, profile))
}

/// `import_source(lang, name, text) -> str`: reads text in another language as Neuron source.
#[pyfunction]
fn import_source(py: Python<'_>, lang: &str, name: &str, text: &str) -> String {
    py.allow_threads(|| api::import(lang, name, text))
}

/// `version() -> str`: versions of the compiler and its formats.
#[pyfunction]
fn version() -> String {
    api::version()
}

/// The `neuron_py` module.
#[pymodule]
fn neuron_py(m: &Bound<'_, PyModule>) -> PyResult<()> {
    m.add_function(wrap_pyfunction!(check, m)?)?;
    m.add_function(wrap_pyfunction!(format, m)?)?;
    m.add_function(wrap_pyfunction!(hover, m)?)?;
    m.add_function(wrap_pyfunction!(definition, m)?)?;
    m.add_function(wrap_pyfunction!(run, m)?)?;
    m.add_function(wrap_pyfunction!(test, m)?)?;
    m.add_function(wrap_pyfunction!(emit, m)?)?;
    m.add_function(wrap_pyfunction!(import_source, m)?)?;
    m.add_function(wrap_pyfunction!(version, m)?)?;
    Ok(())
}
